import { Injectable } from '@angular/core';
import { HttpClient, HttpHeaders } from '@angular/common/http';
import { Observable } from 'rxjs';
console.log("Attendance Service is loaded!");

@Injectable({
  providedIn: 'root'
})


export class AttendanceService {
  private apiUrl = 'http://localhost:3000/api/v1/attendance';

  constructor(private http: HttpClient) { }

  getAllAttendance(): Observable<any> {
    const token = localStorage.getItem('token') || 'Nooo';
    const headers = new HttpHeaders({
      'Authorization': `Bearer ${token}`
    });
    console.log("Token sent:", token);
    return this.http.get<any>(`${this.apiUrl}/allattendance`, { headers });
  }

  addAttendance(data: any): Observable<any> {
    const token = localStorage.getItem('token') || '';

    if (token) {
      try {

        const base64Url = token.split('.')[1];
        const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
        const jsonPayload = decodeURIComponent(atob(base64).split('').map(function (c) {
          return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
        }).join(''));

        const payload = JSON.parse(jsonPayload);
        console.log("Token Payload (User Role):", payload); 
      } catch (e) {
        console.error("Error decoding token", e);
      }
    } else {
      console.log("No token found!");
    }

    const headers = new HttpHeaders({
      'Authorization': `Bearer ${token}`
    });
    return this.http.post<any>(`${this.apiUrl}/create`, data, { headers });
  }

  updateAttendance(id: string, data: any): Observable<any> {
    const token = localStorage.getItem('token') || '';
    const headers = new HttpHeaders({
      'Authorization': `Bearer ${token}`
    });
    return this.http.put<any>(`${this.apiUrl}/update/${id}`, data, { headers });
  }
}
